'use client';

import { useState, type FormEvent, type ReactNode } from 'react';
import Link from 'next/link';
import { Badge, EmptyState, ErrorState, LoadingState, Pagination } from '../../components/shared/ui';
import type {
  CustomerPortalView, DateRange, FinanceDashboardView, InvoiceDetailView, KanbanBucketView,
  InvoiceQuery, InvoiceSummary, LoadState, PageInfo, PaymentQuery, PaymentView, QuarterlyReportView,
  SubscriptionView,
} from './types';

type StateProps = LoadState & { children?: ReactNode; empty?: boolean; emptyMessage?: string };
function RequestState({ loading, error, onRetry, children, empty, emptyMessage }: StateProps) {
  if (loading) return <div className="rounded-2xl border border-slate-200/80 bg-white px-5 shadow-sm"><LoadingState label="Loading from Brightloop…" /></div>;
  if (error) return <ErrorState message={error} retry={onRetry} />;
  if (empty) return <div className="rounded-2xl border border-slate-200/80 bg-white px-5 shadow-sm"><EmptyState title="Nothing to show yet" description={emptyMessage} /></div>;
  return <>{children}</>;
}

function money(value: string, currency: 'INR' = 'INR') {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? new Intl.NumberFormat('en-IN', { style: 'currency', currency, minimumFractionDigits: 2 }).format(numeric) : 'Amount unavailable';
}
function compareMoney(a: string, b: string) {
  const normalize = (value: string) => {
    const [whole = '0', fraction = ''] = value.split('.');
    return { whole: whole.replace(/^0+(?=\d)/, ''), fraction: (fraction + '00').slice(0, 2) };
  };
  const left = normalize(a); const right = normalize(b);
  if (left.whole.length !== right.whole.length) return left.whole.length < right.whole.length ? -1 : 1;
  if (left.whole !== right.whole) return left.whole < right.whole ? -1 : 1;
  return left.fraction === right.fraction ? 0 : left.fraction < right.fraction ? -1 : 1;
}
function date(value?: string | null) {
  if (!value) return '—';
  const parsed = /^\d{4}-\d{2}-\d{2}$/.test(value) ? new Date(`${value}T12:00:00+05:30`) : new Date(value);
  return Number.isNaN(parsed.getTime()) ? '—' : new Intl.DateTimeFormat('en-IN', { dateStyle: 'medium', timeZone: 'Asia/Kolkata' }).format(parsed);
}
function Status({ value }: { value: string }) {
  const normalized = value.toUpperCase();
  const tone = ['PAID','CONFIRMED','ACTIVE','COMPLETED'].includes(normalized) ? 'success' : ['OVERDUE','FAILED','CANCELLED','CLOSED'].includes(normalized) ? 'danger' : ['DRAFT','PENDING','QUEUED','RUNNING','PARTIALLY_PAID'].includes(normalized) ? 'warning' : 'neutral';
  return <Badge tone={tone}>{value.toLowerCase().replaceAll('_', ' ')}</Badge>;
}
function SectionHeading({ title, detail, children }: { title: string; detail?: string; children?: ReactNode }) {
  return <div className="mb-7 flex flex-col items-start justify-between gap-5 xl:flex-row xl:items-end"><div className="min-w-0"><p className="mb-2 text-[11px] font-bold uppercase tracking-[0.18em] text-emerald-600">Brightloop workspace</p><h1 className="text-3xl font-bold tracking-tight text-ink sm:text-[2rem]">{title}</h1>{detail && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{detail}</p>}</div>{children && <div className="w-full xl:w-auto">{children}</div>}</div>;
}
function Card({ title, value, note, mark, tone = 'emerald' }: { title: string; value: string; note?: string; mark: string; tone?: 'emerald' | 'blue' | 'green' | 'amber' }) {
  const tones = { emerald: 'bg-emerald-50 text-emerald-600', blue: 'bg-sky-50 text-sky-600', green: 'bg-emerald-50 text-emerald-700', amber: 'bg-amber-50 text-amber-700' };
  return <article className="group min-w-0 rounded-2xl border border-slate-200/80 bg-white p-5 shadow-sm shadow-slate-900/[0.03] transition duration-200 hover:-translate-y-0.5 hover:shadow-md hover:shadow-slate-900/[0.06]">
    <div className="flex items-start justify-between gap-3"><h2 className="text-sm font-medium leading-5 text-slate-600">{title}</h2><span aria-hidden="true" className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl text-base font-semibold ${tones[tone]}`}>{mark}</span></div>
    <p className="mt-5 break-words text-2xl font-bold tracking-tight tabular-nums text-ink sm:text-[1.8rem]">{value}</p>{note && <p className="mt-2 text-xs leading-5 text-slate-500">{note}</p>}
  </article>;
}
function EmptyRows({ columns, children }: { columns: number; children: ReactNode }) {
  return <tr><td colSpan={columns} className="px-4 py-10 text-center text-sm text-slate-600">{children}</td></tr>;
}
function Pager({ page, onPage }: { page: PageInfo; onPage: (next: number) => void }) {
  return <div className="border-t border-slate-200 px-4 py-3"><Pagination page={page.page} pageSize={page.pageSize} total={page.total} onPageChange={onPage} /></div>;
}

export function FinanceDashboardScreen({ data, loading, error, onRetry, onRangeChange }: LoadState & { data: FinanceDashboardView | null; onRangeChange: (range: DateRange) => void }) {
  const [range, setRange] = useState<DateRange>({ from: '', to: '' });
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onRangeChange(range); }
  return <section className="mx-auto w-full max-w-7xl p-4 sm:p-8">
    <SectionHeading title="Finance overview" detail="A live summary of subscriptions, invoicing, collections and overdue balances.">
      <form onSubmit={submit} className="grid w-full gap-3 rounded-2xl border border-slate-200/80 bg-white p-3 shadow-sm sm:grid-cols-[1fr_1fr_auto] xl:w-auto">
        <label className="grid min-w-0 gap-1.5 text-xs font-semibold text-slate-600">From<input aria-label="From date" type="date" value={range.from} onChange={e => setRange({ ...range, from: e.target.value })} className="min-h-10 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm font-normal text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label>
        <label className="grid min-w-0 gap-1.5 text-xs font-semibold text-slate-600">To<input aria-label="To date" type="date" value={range.to} onChange={e => setRange({ ...range, to: e.target.value })} className="min-h-10 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm font-normal text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label>
        <button className="min-h-10 rounded-xl bg-emerald-600 px-4 py-2 text-sm font-semibold text-white shadow-sm transition hover:bg-emerald-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600">Apply dates</button>
      </form>
    </SectionHeading>
    <RequestState loading={loading} error={error} onRetry={onRetry} empty={!data} emptyMessage="The reporting API returned no finance summary for this period.">
      {data && <><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><p className="flex items-center gap-2 text-xs font-medium text-slate-500"><span aria-hidden="true" className="h-2 w-2 rounded-full bg-emerald-500" />Reporting period: {date(data.range.from)} – {date(data.range.to)} <span className="text-slate-300">·</span> INR <span className="text-slate-300">·</span> Asia/Kolkata</p><span className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-500">Reporting summary</span></div><div className="grid gap-4 sm:grid-cols-2 2xl:grid-cols-5"><Card title="Active subscriptions" value={data.activeSubscriptions.toLocaleString('en-IN')} mark="↻" tone="emerald" /><Card title="Invoiced" value={money(data.invoiced)} note="Issued invoice totals" mark="▤" tone="blue" /><Card title="Collected" value={money(data.collected)} note="Verified payments only" mark="₹" tone="green" /><Card title="Outstanding" value={money(data.outstanding)} note="Current open balance" mark="◷" tone="emerald" /><Card title="Overdue invoices" value={data.overdueCount.toLocaleString('en-IN')} note={`${money(data.overdueBalance)} overdue`} mark="!" tone="amber" /></div>
        <div className="mt-5 grid gap-4 lg:grid-cols-[1.35fr_1fr]"><article className="rounded-2xl border border-slate-200/80 bg-white p-5 shadow-sm sm:p-6"><div className="flex items-start gap-3"><span aria-hidden="true" className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-emerald-50 font-semibold text-emerald-600">↗</span><div><h2 className="font-semibold text-ink">Collections at a glance</h2><p className="mt-1 text-sm leading-6 text-slate-600">Collected and invoiced amounts follow the selected reporting window.</p></div></div><div className="mt-5 grid gap-4 border-t border-slate-100 pt-4 sm:grid-cols-2"><div><p className="text-xs font-medium text-slate-500">Collected in period</p><p className="mt-1 text-lg font-bold text-ink">{money(data.collected)}</p></div><div><p className="text-xs font-medium text-slate-500">Invoiced in period</p><p className="mt-1 text-lg font-bold text-ink">{money(data.invoiced)}</p></div></div></article><article className="rounded-2xl border border-amber-200/80 bg-amber-50/60 p-5 shadow-sm sm:p-6"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-amber-800">Needs attention</p><h2 className="mt-2 font-semibold text-ink">Overdue invoices</h2></div><span aria-hidden="true" className="grid h-10 w-10 place-items-center rounded-xl bg-amber-100 font-bold text-amber-700">!</span></div><p className="mt-3 text-2xl font-bold text-ink">{data.overdueCount.toLocaleString('en-IN')} <span className="text-sm font-medium text-slate-600">invoices</span></p><p className="mt-1 text-sm text-slate-600">{money(data.overdueBalance)} currently overdue</p><Link href="/finance/invoices" className="mt-4 inline-flex min-h-10 items-center rounded-xl border border-amber-200 bg-white px-3 text-sm font-semibold text-amber-900 transition hover:bg-amber-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-700">Review invoices <span className="ml-2" aria-hidden="true">→</span></Link></article></div></>}
    </RequestState>
  </section>;
}

export function InvoiceListScreen({ rows, pagination, loading, error, onRetry, onQuery, onOpen }: LoadState & { rows: InvoiceSummary[]; pagination: PageInfo; onQuery: (query: InvoiceQuery) => void; onOpen: (invoiceId: string) => void }) {
  const [query, setQuery] = useState<InvoiceQuery>({ page: pagination.page, search: '', status: '', dueFrom: '', dueTo: '' });
  function update<K extends keyof InvoiceQuery>(key: K, value: InvoiceQuery[K]) { setQuery(current => ({ ...current, [key]: value })); }
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onQuery({ ...query, page: 1 }); }
  return <section className="mx-auto w-full max-w-7xl p-4 sm:p-8"><SectionHeading title="Invoices" detail="Search, filter and review invoices returned by the finance API." />
    <form onSubmit={submit} className="mb-5 grid gap-3 rounded-2xl border border-slate-200/80 bg-white p-4 shadow-sm shadow-slate-900/[0.03] sm:grid-cols-2 xl:grid-cols-5">
      <label className="grid min-w-0 gap-1.5 text-xs font-semibold text-slate-600">Search<input value={query.search} onChange={e => update('search', e.target.value)} placeholder="Invoice or customer" className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label>
      <label className="grid min-w-0 gap-1.5 text-xs font-semibold text-slate-600">Status<select value={query.status} onChange={e => update('status', e.target.value)} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100"><option value="">All statuses</option>{['DRAFT','CONFIRMED','SENT','PARTIALLY_PAID','PAID','OVERDUE','CANCELLED'].map(x => <option key={x}>{x}</option>)}</select></label>
      <label className="grid min-w-0 gap-1.5 text-xs font-semibold text-slate-600">Due from<input type="date" value={query.dueFrom} onChange={e => update('dueFrom', e.target.value)} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label>
      <label className="grid min-w-0 gap-1.5 text-xs font-semibold text-slate-600">Due to<input type="date" value={query.dueTo} onChange={e => update('dueTo', e.target.value)} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label>
      <button className="self-end rounded-lg bg-emerald-600 px-3 py-2 text-sm font-semibold text-white shadow-sm transition hover:bg-emerald-700">Apply filters</button>
    </form>
      <div className="overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03]"><RequestState loading={loading} error={error} onRetry={onRetry} empty={!rows.length} emptyMessage="No invoices match these filters."><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="border-b border-slate-100 bg-slate-50/70 text-[11px] font-bold uppercase tracking-wider text-slate-500"><tr>{['Invoice','Customer','Issued','Due date','Total','Balance','Status'].map(h => <th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{rows.map(row => <tr key={row.id} className="border-t border-slate-100 transition-colors hover:bg-emerald-50/40"><td className="px-4 py-3"><button type="button" onClick={() => onOpen(row.id)} className="font-semibold text-emerald underline-offset-2 hover:underline">{row.number}</button></td><td className="px-4 py-3">{row.customerName}{row.customerEmail && <span className="block text-xs text-slate-500">{row.customerEmail}</span>}</td><td className="px-4 py-3">{date(row.issueDate)}</td><td className="px-4 py-3">{date(row.dueDate)}</td><td className="px-4 py-3">{money(row.total)}</td><td className="px-4 py-3">{money(row.balance)}</td><td className="px-4 py-3"><Status value={row.overdue ? 'OVERDUE' : row.status} /></td></tr>)}{!rows.length && <EmptyRows columns={7}>No matching invoices.</EmptyRows>}</tbody></table></div></RequestState><Pager page={pagination} onPage={next => onQuery({ ...query, page: next })} /></div>
  </section>;
}

export function FinancePaymentsScreen({ rows, pagination, loading, error, onRetry, onQuery }: LoadState & { rows: PaymentView[]; pagination: PageInfo; onQuery: (query: PaymentQuery) => void }) {
  const [query, setQuery] = useState<PaymentQuery>({ page: pagination.page, search: '', status: '', method: '', paidFrom: '', paidTo: '' });
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onQuery({ ...query, page: 1 }); }
  return <section className="mx-auto w-full max-w-7xl p-4 sm:p-8"><SectionHeading title="Payments" detail="Payment history returned by the authenticated finance API." /><form onSubmit={submit} className="mb-4 grid gap-3 rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-4 sm:grid-cols-2 xl:grid-cols-12"><label className="grid min-w-0 gap-1 text-xs font-medium text-slate-600 xl:col-span-3">Search<input value={query.search} onChange={e => setQuery({ ...query, search: e.target.value })} placeholder="Invoice, note or reference" className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label><label className="grid min-w-0 gap-1 text-xs font-medium text-slate-600 xl:col-span-2">Status<select value={query.status} onChange={e => setQuery({ ...query, status: e.target.value })} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100"><option value="">All statuses</option>{['PENDING','CONFIRMED','FAILED','VOID'].map(v => <option key={v}>{v}</option>)}</select></label><label className="grid min-w-0 gap-1 text-xs font-medium text-slate-600 xl:col-span-2">Method<select value={query.method} onChange={e => setQuery({ ...query, method: e.target.value })} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100"><option value="">All methods</option>{['CASH','BANK_TRANSFER','UPI','CHEQUE','CARD','OTHER'].map(v => <option key={v}>{v}</option>)}</select></label><label className="grid min-w-0 gap-1 text-xs font-medium text-slate-600 xl:col-span-2">Paid from<input type="date" value={query.paidFrom} onChange={e => setQuery({ ...query, paidFrom: e.target.value })} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label><label className="grid min-w-0 gap-1 text-xs font-medium text-slate-600 xl:col-span-2">Paid to<input type="date" value={query.paidTo} onChange={e => setQuery({ ...query, paidTo: e.target.value })} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label><button className="w-full min-w-0 self-end rounded-lg bg-emerald-600 px-3 py-2 text-sm font-semibold text-white shadow-sm transition hover:bg-emerald-700 xl:col-span-1">Apply</button></form><div className="overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03]"><RequestState loading={loading} error={error} onRetry={onRetry} empty={!rows.length} emptyMessage="No payments match these filters."><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="border-b border-slate-100 bg-slate-50/70 text-[11px] font-bold uppercase tracking-wider text-slate-500"><tr>{['Paid at','Invoice','Method','Amount','Status','Reference','Note'].map(h => <th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{rows.map(row => <tr key={row.id} className="border-t border-slate-100 transition-colors hover:bg-emerald-50/40"><td className="px-4 py-3">{date(row.paidAt)}</td><td className="px-4 py-3">{row.invoiceNumber || '—'}</td><td className="px-4 py-3">{row.method}</td><td className="px-4 py-3">{money(row.amount)}</td><td className="px-4 py-3"><Status value={row.status} /></td><td className="px-4 py-3">{row.reference || '—'}</td><td className="max-w-56 truncate px-4 py-3">{row.note || '—'}</td></tr>)}</tbody></table></div></RequestState><Pager page={pagination} onPage={page => onQuery({ ...query, page })} /></div></section>;
}

type InvoiceAction = 'confirm' | 'cancel' | 'send';
export function InvoiceDetailScreen({ invoice, loading, error, onRetry, permissions, onAction, onDownload, onRecordPayment }: LoadState & {
  invoice: InvoiceDetailView | null;
  permissions: Partial<Record<InvoiceAction, boolean>>;
  onAction: (action: InvoiceAction) => Promise<void>;
  onDownload: () => Promise<void>;
  onRecordPayment: (input: { method: string; amount: string; date: string; note: string }) => Promise<void>;
}) {
  const [pending, setPending] = useState(''); const [actionError, setActionError] = useState('');
  const [method, setMethod] = useState('Bank transfer'); const [amount, setAmount] = useState(''); const [paidAt, setPaidAt] = useState(''); const [note, setNote] = useState('');
  async function act(name: InvoiceAction) { const prompt = name === 'confirm' ? 'Confirm this invoice?' : name === 'cancel' ? 'Cancel this invoice? This action may affect the billing record.' : 'Send this invoice to the customer?'; if (!window.confirm(prompt)) return; setPending(name); setActionError(''); try { await onAction(name); } catch (e) { setActionError(e instanceof Error ? e.message : 'The invoice action failed.'); } finally { setPending(''); } }
  async function pay(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!invoice || !/^\d+(\.\d{1,2})?$/.test(amount) || compareMoney(amount, '0.00') <= 0 || !paidAt) { setActionError('Enter a positive amount with up to two decimals and a payment date.'); return; } if (compareMoney(amount, invoice.balance) > 0) { setActionError('Payment amount cannot exceed the outstanding balance.'); return; } setPending('payment'); setActionError(''); try { await onRecordPayment({ method, amount, date: paidAt, note }); setAmount(''); setNote(''); } catch (e) { setActionError(e instanceof Error ? e.message : 'Payment could not be recorded.'); } finally { setPending(''); } }
  async function download() { setPending('download'); setActionError(''); try { await onDownload(); } catch (e) { setActionError(e instanceof Error ? e.message : 'Invoice download failed.'); } finally { setPending(''); } }
  return <section className="mx-auto w-full max-w-6xl p-4 sm:p-8"><SectionHeading title={invoice ? `Invoice ${invoice.number}` : 'Invoice detail'} detail="Snapshot details, payment history and invoice events." />
    <RequestState loading={loading} error={error} onRetry={onRetry} empty={!invoice} emptyMessage="Invoice details are not available.">{invoice && <><div className="mb-4 flex flex-wrap items-center gap-2"><Status value={invoice.status} />{(['confirm','cancel','send'] as const).map(action => permissions[action] && <button key={action} disabled={!!pending} onClick={() => void act(action)} className="inline-flex min-h-10 items-center justify-center rounded-xl border border-slate-200 bg-white px-4 text-sm font-semibold capitalize text-slate-700 shadow-sm transition hover:border-emerald-200 hover:bg-emerald-50 disabled:cursor-not-allowed disabled:opacity-50">{pending === action ? 'Working…' : action}</button>)}<button type="button" disabled={!!pending} onClick={() => void download()} className="inline-flex min-h-10 items-center justify-center rounded-xl border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-700 shadow-sm transition hover:border-emerald-200 hover:bg-emerald-50 disabled:cursor-not-allowed disabled:opacity-50">{pending === 'download' ? 'Preparing…' : 'Print / download'}</button></div>
      {actionError && <p role="alert" className="mb-4 rounded-lg border border-rose-200 bg-rose-50 p-3 text-sm text-rose-800">{actionError}</p>}
      <div className="grid gap-4 lg:grid-cols-[1.5fr_1fr]"><section className="space-y-4"><article className="rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Bill to</h2><p className="mt-3 font-medium">{invoice.customerName}</p><p className="text-sm text-slate-600">{invoice.customerEmail}</p>{invoice.customerAddress && <p className="mt-1 whitespace-pre-line text-sm text-slate-600">{invoice.customerAddress}</p>}<p className="mt-4 text-sm text-slate-600">Issued {date(invoice.issueDate)} · Due {date(invoice.dueDate)}</p></article>
        <article className="overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03]"><div className="overflow-x-auto"><table className="w-full min-w-[540px] text-left text-sm"><thead className="border-b border-slate-100 bg-slate-50/70 text-[11px] font-bold uppercase tracking-wider text-slate-500"><tr>{['Description','Qty','Unit price','Discount','Line total'].map(h => <th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{invoice.lines.map(line => <tr key={line.id} className="border-t border-slate-100 transition-colors hover:bg-emerald-50/40"><td className="px-4 py-3">{line.description}{line.taxes.map(t => <span key={t.name} className="block text-xs text-slate-500">{t.name} ({t.rate}%): {money(t.amount)}</span>)}</td><td className="px-4 py-3">{line.quantity}</td><td className="px-4 py-3">{money(line.unitPrice)}</td><td className="px-4 py-3">{money(line.discountAmount)}</td><td className="px-4 py-3">{money(line.lineTotal)}</td></tr>)}</tbody></table></div><dl className="ml-auto grid max-w-sm grid-cols-2 gap-x-8 gap-y-2 p-5 text-sm"><dt className="text-slate-600">Subtotal</dt><dd className="text-right">{money(invoice.subtotal)}</dd><dt className="text-slate-600">Discounts</dt><dd className="text-right">−{money(invoice.discountTotal)}</dd><dt className="text-slate-600">Taxes</dt><dd className="text-right">{money(invoice.taxTotal)}</dd><dt className="border-t border-slate-200 pt-2 font-semibold">Total</dt><dd className="border-t border-slate-200 pt-2 text-right font-semibold">{money(invoice.total)}</dd><dt className="font-semibold">Outstanding</dt><dd className="text-right font-semibold">{money(invoice.balance)}</dd></dl></article>
      </section><aside className="space-y-4"><section className="rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Record manual payment</h2><p className="mt-1 text-xs text-slate-500">Partial payments are supported. The server determines invoice status.</p><form onSubmit={e => void pay(e)} className="mt-4 grid gap-3"><label className="grid gap-1 text-xs font-medium">Method<select value={method} onChange={e => setMethod(e.target.value)} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100">{['Bank transfer','Cash','Card','Cheque','Other'].map(x => <option key={x}>{x}</option>)}</select></label><label className="grid gap-1 text-xs font-medium">Amount (INR)<input required inputMode="decimal" value={amount} onChange={e => setAmount(e.target.value)} pattern="[0-9]+(\.[0-9]{1,2})?" className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label><label className="grid gap-1 text-xs font-medium">Payment date<input required type="date" value={paidAt} onChange={e => setPaidAt(e.target.value)} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label><label className="grid gap-1 text-xs font-medium">Note (optional)<textarea value={note} onChange={e => setNote(e.target.value)} rows={2} className="min-h-10 w-full min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm text-slate-800 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100" /></label><button disabled={!!pending} className="rounded-lg bg-emerald-600 px-3 py-2 text-sm font-semibold text-white shadow-sm transition hover:bg-emerald-700 disabled:opacity-50">{pending === 'payment' ? 'Saving…' : 'Record payment'}</button></form></section>
        <section className="rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Payments</h2>{invoice.payments.length ? <ul className="mt-3 divide-y divide-slate-100">{invoice.payments.map(p => <li key={p.id} className="py-3"><div className="flex justify-between gap-3"><b className="text-sm">{money(p.amount)}</b><Status value={p.status} /></div><p className="mt-1 text-xs text-slate-600">{p.method} · {date(p.paidAt)}</p>{p.note && <p className="mt-1 text-xs text-slate-500">{p.note}</p>}</li>)}</ul> : <p className="mt-3 text-sm text-slate-600">No payments recorded.</p>}</section>
        <section className="rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Invoice history</h2><ol className="mt-3 space-y-3">{invoice.history.map((h, i) => <li key={`${h.status}-${h.at}-${i}`} className="border-l-2 border-emerald/30 pl-3"><div className="flex items-center gap-2"><Status value={h.status} /><time className="text-xs text-slate-500">{date(h.at)}</time></div>{h.note && <p className="mt-1 text-xs text-slate-600">{h.note}</p>}</li>)}</ol></section></aside></div></>}</RequestState>
  </section>;
}

export function DueDateKanbanScreen({ buckets, loading, error, onRetry, onOpen, onPage }: LoadState & { buckets: KanbanBucketView[]; onOpen: (invoiceId: string) => void; onPage: (bucket: string, page: number) => void }) {
  return <section className="mx-auto w-full max-w-7xl p-4 sm:p-8"><SectionHeading title="Due-date board" detail="Buckets and counts come from the reporting API. Opening a card never changes its due date or status." /><RequestState loading={loading} error={error} onRetry={onRetry} empty={!buckets.some(b => b.count)} emptyMessage="No invoice buckets were returned."><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{buckets.map(bucket => <section key={bucket.key} aria-label={`${bucket.label}, ${bucket.count} invoices`} className="rounded-xl border border-slate-200 bg-slate-50 p-3"><header className="mb-3 flex items-center justify-between"><h2 className="font-semibold">{bucket.label}</h2><span className="rounded-full bg-white px-2 py-1 text-xs">{bucket.count}</span></header><ul className="space-y-2">{bucket.invoices.map(item => <li key={item.id}><button type="button" onClick={() => onOpen(item.id)} className="w-full rounded-lg border border-slate-200 bg-white p-3 text-left hover:border-emerald"><span className="flex items-center justify-between gap-2"><b className="text-sm">{item.number}</b><Status value={item.overdue ? 'OVERDUE' : item.status} /></span><span className="mt-2 block text-xs text-slate-600">{item.customerName} · due {date(item.dueDate)}</span><span className="mt-2 block text-sm font-semibold">Balance {money(item.balance)}</span></button></li>)}</ul>{bucket.count > bucket.invoices.length && <div className="mt-3"><Pager page={bucket.pagination} onPage={page => onPage(bucket.key, page)} /></div>}</section>)}</div></RequestState></section>;
}

export function QuarterlyReportsScreen({ reports, loading, error, onRetry, onRun }: LoadState & { reports: QuarterlyReportView[]; onRun: () => Promise<void> }) {
  const [pending, setPending] = useState(''); const [actionError, setActionError] = useState('');
  async function run() { setPending('run'); setActionError(''); try { await onRun(); } catch (e) { setActionError(e instanceof Error ? e.message : 'The report could not be queued.'); } finally { setPending(''); } }
  return <section className="mx-auto w-full max-w-6xl p-4 sm:p-8"><SectionHeading title="Quarterly reports" detail="Run status is refreshed from the reporting service."><button type="button" disabled={!!pending} onClick={() => void run()} className="rounded-lg bg-emerald-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">{pending === 'run' ? 'Submitting…' : 'Run report'}</button></SectionHeading><p className="mb-3 text-xs text-slate-600">The current API has no direct report download route. Delivery details below come from each server report record.</p>{actionError && <p role="alert" className="mb-3 rounded-lg bg-rose-50 p-3 text-sm text-rose-800">{actionError}</p>}<div className="overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03]"><RequestState loading={loading} error={error} onRetry={onRetry} empty={!reports.length} emptyMessage="No quarterly report runs were returned."><div className="overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead className="border-b border-slate-100 bg-slate-50/70 text-[11px] font-bold uppercase tracking-wider text-slate-500"><tr>{['Period','Status','Created','Completed','Delivery'].map(h => <th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{reports.map(report => <tr key={report.id} className="border-t border-slate-100 transition-colors hover:bg-emerald-50/40"><td className="px-4 py-3 font-medium">{report.period}</td><td className="px-4 py-3"><Status value={report.status} /></td><td className="px-4 py-3">{date(report.createdAt)}</td><td className="px-4 py-3">{date(report.completedAt)}</td><td className="max-w-sm px-4 py-3 text-xs text-slate-600">{report.deliveryNote}</td></tr>)}</tbody></table></div></RequestState></div></section>;
}

export function CustomerPortalScreen({ customer, loading, error, onRetry, onOpenSubscription, onOpenInvoice, pagination, onPage, paymentPagination, onPaymentPage }: LoadState & { customer: CustomerPortalView | null; onOpenSubscription: (id: string) => void; onOpenInvoice: (id: string) => void; pagination: PageInfo; onPage: (page: number) => void; paymentPagination: PageInfo; onPaymentPage: (page: number) => void }) {
  return <section className="mx-auto w-full max-w-7xl p-4 sm:p-8">
    <SectionHeading title="Your account" detail="A clear view of your balance, invoices, subscriptions and payment history." />
    <RequestState loading={loading} error={error} onRetry={onRetry} empty={!customer} emptyMessage="Your account information is not available yet.">
      {customer && <>
        <section className="mb-5 overflow-hidden rounded-3xl border border-emerald-100 bg-gradient-to-br from-emerald-50 via-white to-sky-50 p-5 shadow-sm sm:p-7">
          <div className="flex flex-wrap items-start justify-between gap-4">
            <div><p className="text-xs font-bold uppercase tracking-[0.16em] text-emerald-600">Customer workspace</p><h2 className="mt-2 text-2xl font-bold tracking-tight tabular-nums text-ink">Welcome, {customer.displayName}</h2><p className="mt-1 text-sm text-slate-600">{customer.billingEmail}</p></div>
            <span className="grid h-12 w-12 place-items-center rounded-2xl bg-white text-xl font-bold text-emerald-600 shadow-sm" aria-hidden="true">{customer.displayName.slice(0, 1).toUpperCase()}</span>
          </div>
          <div className="mt-6 grid gap-3 sm:grid-cols-3">
            <Card title="Outstanding balance" value={money(customer.outstanding)} mark="◷" tone="emerald" />
            <Card title="Invoices" value={pagination.total.toLocaleString('en-IN')} mark="▤" tone="blue" />
            <Card title="Recorded payments" value={paymentPagination.total.toLocaleString('en-IN')} mark="₹" tone="green" />
          </div>
          {customer.invoices.some(invoice => invoice.overdue && invoice.balance !== '0.00') && <div role="alert" className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-4"><div><p className="font-semibold text-amber-950">An invoice needs your attention</p><p className="mt-1 text-sm text-amber-900">Review the due date and outstanding balance in your invoice list.</p></div><span className="rounded-full bg-white px-3 py-1.5 text-xs font-semibold text-amber-900">Overdue</span></div>}
        </section>
        <div className="grid gap-5 xl:grid-cols-2">
          <section className="rounded-2xl border border-slate-200/80 bg-white p-5 shadow-sm sm:p-6">
            <div className="mb-4 flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-slate-400">Account</p><h2 className="mt-1 text-lg font-semibold text-ink">Subscriptions</h2></div><span className="grid h-9 w-9 place-items-center rounded-xl bg-emerald-50 font-semibold text-emerald-600" aria-hidden="true">↻</span></div>
            {customer.subscriptions === null ? <div className="rounded-xl border border-dashed border-slate-200 bg-slate-50 p-4"><p className="font-medium text-slate-800">Subscription list unavailable</p><p className="mt-1 text-sm leading-5 text-slate-600">The current frontend contract does not expose your paginated subscription list yet.</p></div> : customer.subscriptions.length ? <ul className="divide-y divide-slate-100">{customer.subscriptions.map(subscription => <li key={subscription.id} className="flex flex-wrap items-center justify-between gap-3 py-4"><div className="min-w-0"><button type="button" onClick={() => onOpenSubscription(subscription.id)} className="font-semibold text-emerald-700 underline-offset-2 hover:underline">{subscription.number}</button><p className="mt-1 text-sm text-slate-600">{subscription.planName} · {money(subscription.amount)}</p><p className="mt-1 text-xs text-slate-500">Next billing {date(subscription.nextBillingDate)}</p></div><Status value={subscription.status} /></li>)}</ul> : <EmptyState title="No subscriptions" description="There are no subscriptions linked to your account." />}
          </section>
          <section className="overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-sm">
            <header className="flex items-center justify-between gap-3 p-5 sm:p-6"><div><p className="text-xs font-bold uppercase tracking-wider text-slate-400">Billing</p><h2 className="mt-1 text-lg font-semibold text-ink">Invoices</h2></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold text-slate-600">{pagination.total.toLocaleString('en-IN')} total</span></header>
            {customer.invoices.length ? <ul className="divide-y divide-slate-100 border-t border-slate-100 transition-colors hover:bg-emerald-50/40">{customer.invoices.map(invoice => <li key={invoice.id} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4 transition hover:bg-emerald-50/40 sm:px-6"><div className="min-w-0"><button type="button" onClick={() => onOpenInvoice(invoice.id)} className="font-semibold text-emerald-700 underline-offset-2 hover:underline">{invoice.number}</button><p className="mt-1 text-sm text-slate-500">Due {date(invoice.dueDate)}</p><p className="mt-1 text-xs text-slate-600">Balance {money(invoice.balance)}</p></div><Status value={invoice.overdue ? 'OVERDUE' : invoice.status} /></li>)}</ul> : <div className="border-t border-slate-100 transition-colors hover:bg-emerald-50/40 px-5"><EmptyState title="No invoices yet" description="Your invoices will appear here when they are issued." /></div>}
            <div className="border-t border-slate-100 transition-colors hover:bg-emerald-50/40 px-5 py-3 sm:px-6"><Pagination page={pagination.page} pageSize={pagination.pageSize} total={pagination.total} onPageChange={onPage} /></div>
          </section>
        </div>
        <section className="mt-5 overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-sm">
          <header className="flex flex-wrap items-center justify-between gap-3 p-5 sm:p-6"><div><p className="text-xs font-bold uppercase tracking-wider text-slate-400">Activity</p><h2 className="mt-1 text-lg font-semibold text-ink">Payment history</h2></div><span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-800">Verified records</span></header>
          <div className="px-5 sm:px-6"><PaymentHistory payments={customer.payments} /></div>
          <div className="border-t border-slate-100 transition-colors hover:bg-emerald-50/40 px-5 py-3 sm:px-6"><Pagination page={paymentPagination.page} pageSize={paymentPagination.pageSize} total={paymentPagination.total} onPageChange={onPaymentPage} /></div>
        </section>
      </>}
    </RequestState>
  </section>;
}
export function CustomerInvoiceScreen({ invoice, loading, error, onRetry, onCheckout }: LoadState & { invoice: InvoiceDetailView | null; onCheckout: (update: (state: 'pending' | 'verified' | 'failed' | 'dismissed', message?: string) => void) => Promise<void> }) {
  const [pending, setPending] = useState(false); const [paymentState, setPaymentState] = useState(''); const [paymentError, setPaymentError] = useState('');
  async function pay() { if (!invoice || pending) return; setPending(true); setPaymentState('Checkout opened. Payment remains pending until the server verifies it.'); setPaymentError(''); try { await onCheckout((state, message) => { if (state === 'verified') setPaymentState(message || 'Payment verified by Brightloop.'); else if (state === 'pending') setPaymentState(message || 'Payment pending server verification.'); else { setPaymentState(''); setPaymentError(message || (state === 'dismissed' ? 'Checkout was dismissed. You can retry when ready.' : 'Payment verification failed. You can retry.')); } }); } catch (e) { setPaymentState(''); setPaymentError(e instanceof Error ? e.message : 'Checkout could not be completed.'); } finally { setPending(false); } }
  const payable = invoice && ['CONFIRMED','SENT','PARTIALLY_PAID'].includes(invoice.status) && invoice.balance !== '0.00';
  return <section className="mx-auto w-full max-w-5xl p-4 sm:p-8"><SectionHeading title={invoice ? `Invoice ${invoice.number}` : 'Invoice detail'} detail="Your invoice snapshot, balance and recorded payments." /><RequestState loading={loading} error={error} onRetry={onRetry} empty={!invoice} emptyMessage="This invoice is unavailable in your account.">{invoice && <><div className="grid gap-4 lg:grid-cols-[1.5fr_1fr]"><article className="overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 p-5"><div><h2 className="font-semibold">{invoice.customerName}</h2><p className="text-sm text-slate-600">{invoice.customerEmail}</p><p className="mt-2 text-xs text-slate-500">Issued {date(invoice.issueDate)} · Due {date(invoice.dueDate)}</p></div><Status value={invoice.status} /></div><div className="overflow-x-auto"><table className="w-full min-w-[540px] text-left text-sm"><thead className="border-b border-slate-100 bg-slate-50/70 text-[11px] font-bold uppercase tracking-wider text-slate-500"><tr>{['Description','Qty','Unit price','Discount','Total'].map(label => <th key={label} className="px-4 py-3">{label}</th>)}</tr></thead><tbody>{invoice.lines.map(line => <tr key={line.id} className="border-t border-slate-100 transition-colors hover:bg-emerald-50/40"><td className="px-4 py-3">{line.description}{line.taxes.map(tax => <span key={tax.name} className="block text-xs text-slate-500">{tax.name} ({tax.rate}%): {money(tax.amount)}</span>)}</td><td className="px-4 py-3">{line.quantity}</td><td className="px-4 py-3">{money(line.unitPrice)}</td><td className="px-4 py-3">{money(line.discountAmount)}</td><td className="px-4 py-3">{money(line.lineTotal)}</td></tr>)}</tbody></table></div><dl className="ml-auto grid max-w-sm grid-cols-2 gap-x-6 gap-y-2 p-5 text-sm"><dt className="text-slate-600">Subtotal</dt><dd className="text-right">{money(invoice.subtotal)}</dd><dt className="text-slate-600">Discount</dt><dd className="text-right">−{money(invoice.discountTotal)}</dd><dt className="text-slate-600">Tax</dt><dd className="text-right">{money(invoice.taxTotal)}</dd><dt className="border-t border-slate-200 pt-2 font-semibold">Total</dt><dd className="border-t border-slate-200 pt-2 text-right font-semibold">{money(invoice.total)}</dd><dt className="font-semibold">Outstanding</dt><dd className="text-right font-semibold">{money(invoice.balance)}</dd></dl></article><aside className="space-y-4"><section className="rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Online payment</h2><p className="mt-2 text-sm text-slate-600">Pay the outstanding INR balance using secure Razorpay test checkout.</p>{paymentError && <p role="alert" className="mt-3 rounded-lg bg-rose-50 p-3 text-sm text-rose-800">{paymentError}</p>}{paymentState && <p role="status" aria-live="polite" className="mt-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-950">{paymentState}</p>}{payable && <button type="button" disabled={pending} onClick={() => void pay()} className="mt-4 min-h-10 w-full rounded-lg bg-emerald-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">{pending ? 'Starting secure checkout…' : `Pay ${money(invoice.balance)}`}</button>}{!payable && <p className="mt-3 text-sm text-slate-600">There is no payable balance for this invoice.</p>}</section><section className="rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Payment history</h2><PaymentHistory payments={invoice.payments} /></section><section className="rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Invoice history</h2><ol className="mt-3 space-y-3">{invoice.history.map((event, index) => <li key={`${event.status}-${event.at}-${index}`} className="border-l-2 border-emerald/30 pl-3"><Status value={event.status} /><time className="ml-2 text-xs text-slate-500">{date(event.at)}</time>{event.note && <p className="mt-1 text-xs text-slate-600">{event.note}</p>}</li>)}</ol></section></aside></div></>}</RequestState></section>;
}

function PaymentHistory({ payments }: { payments: PaymentView[] }) {
  if (!payments.length) return <p className="mt-3 text-sm text-slate-600">No payment records were returned.</p>;
  return <div className="mt-3 overflow-x-auto"><table className="w-full min-w-[480px] text-left text-sm"><thead className="text-xs uppercase text-slate-500"><tr>{['Date','Method','Amount','Status','Note'].map(h => <th key={h} className="px-3 py-2">{h}</th>)}</tr></thead><tbody>{payments.map(payment => <tr key={payment.id} className="border-t border-slate-100 transition-colors hover:bg-emerald-50/40"><td className="px-3 py-3">{date(payment.paidAt)}</td><td className="px-3 py-3">{payment.method}</td><td className="px-3 py-3">{money(payment.amount)}</td><td className="px-3 py-3"><Status value={payment.status} /></td><td className="px-3 py-3">{payment.note || '—'}</td></tr>)}</tbody></table></div>;
}

export function SubscriptionDetailScreen({ subscription, loading, error, onRetry, onAction }: LoadState & {
  subscription: SubscriptionView | null;
  onAction: (action: 'pause' | 'resume' | 'close') => Promise<void>;
}) {
  const [pending, setPending] = useState(''); const [errorMessage, setErrorMessage] = useState('');
  async function action(name: 'pause'|'resume'|'close') { const label = name === 'close' ? 'Close this subscription?' : `${name[0].toUpperCase()}${name.slice(1)} this subscription?`; if (!window.confirm(`${label} Changes apply according to the plan's billing rules.`)) return; setPending(name); setErrorMessage(''); try { await onAction(name); } catch (e) { setErrorMessage(e instanceof Error ? e.message : 'Subscription update failed.'); } finally { setPending(''); } }
  return <section className="mx-auto w-full max-w-5xl p-4 sm:p-8"><SectionHeading title={subscription ? subscription.number : 'Subscription details'} detail="Actions depend on the subscription's plan permissions." /><RequestState loading={loading} error={error} onRetry={onRetry} empty={!subscription} emptyMessage="Subscription details are not available.">{subscription && <><section className="rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-semibold">{subscription.planName}</h2><p className="mt-1 text-sm text-slate-600">{subscription.status} · {money(subscription.amount)} INR</p></div><Status value={subscription.status} /></div><dl className="mt-5 grid gap-3 text-sm sm:grid-cols-3"><div><dt className="text-slate-500">Start date</dt><dd className="font-medium">{date(subscription.startDate)}</dd></div><div><dt className="text-slate-500">End date</dt><dd className="font-medium">{date(subscription.expiryDate)}</dd></div><div><dt className="text-slate-500">Next billing</dt><dd className="font-medium">Not provided by the subscription API</dd></div></dl></section>
    {errorMessage && <p role="alert" className="mt-4 rounded-lg bg-rose-50 p-3 text-sm text-rose-800">{errorMessage}</p>}
    <section className="mt-4 rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Plan items and add-ons</h2><p className="mt-1 text-xs text-slate-500">Quantity and add-on edits belong to the next billing period. This API currently exposes no customer line-change endpoint.</p><ul className="mt-3 divide-y divide-slate-100">{subscription.lines.map(line => <li key={line.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="font-medium">{line.description} {line.isAddon && <span className="text-xs text-emerald">Add-on</span>}</p><p className="text-xs text-slate-500">{line.quantity} × {money(line.agreedPrice)}</p></div><span className="text-xs text-slate-500">Read only</span></li>)}</ul></section>
    {subscription.history?.length ? <section className="mt-4 rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Subscription history</h2><ol className="mt-3 space-y-3">{subscription.history.map((event, index) => <li key={`${event.status}-${event.at}-${index}`} className="border-l-2 border-emerald/30 pl-3"><Status value={event.status} /><time className="ml-2 text-xs text-slate-500">{date(event.at)}</time>{event.note && <p className="mt-1 text-xs text-slate-600">{event.note}</p>}</li>)}</ol></section> : null}
    <section className="mt-4 rounded-2xl border border-slate-200/80 bg-white shadow-sm shadow-slate-900/[0.03] p-5"><h2 className="font-semibold">Available actions</h2><div className="mt-3 flex flex-wrap gap-2">{subscription.allowPause && subscription.status === 'ACTIVE' && <p className="basis-full text-sm text-amber-900">Pause is unavailable here: the current API changes status immediately, while the agreed billing rule requires a boundary-effective pause.</p>}{subscription.status === 'PAUSED' && subscription.allowRenewal && <ActionButton name="Resume" pending={pending === 'resume'} disabled={!!pending} onClick={() => void action('resume')} />}{subscription.allowEarlyClosure && ['DRAFT','QUOTATION','CONFIRMED','ACTIVE','PAUSED'].includes(subscription.status) && <ActionButton name="Close" pending={pending === 'close'} disabled={!!pending} onClick={() => void action('close')} />}</div></section></>}</RequestState></section>;
}
function ActionButton({ name, pending, disabled, onClick }: { name: string; pending: boolean; disabled: boolean; onClick: () => void }) { return <button type="button" disabled={disabled} onClick={onClick} className="inline-flex min-h-10 items-center justify-center rounded-xl border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-700 shadow-sm transition hover:border-emerald-200 hover:bg-emerald-50 disabled:cursor-not-allowed disabled:opacity-50">{pending ? `${name}…` : name}</button>; }
